/// The index of the node with store id @p id, or -1. Linear over 160 nodes: a lookup, not a hot path.
constexpr int find_node(std::string_view id)
{
    for (int i = 0; i < node_count; ++i)
        if (id == nodes[static_cast<std::size_t>(i)].id)
            return i;
    return -1;
}

